const code = `// ov-reddit.mjs — 用 ArcticShift 抓 Reddit 帖子（串行，间隔>=13s，limit=25 上限）
// 用法: node ov-reddit.mjs <targets.json> [outdir]
import { execFile } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36';
const PROXY = 'http://127.0.0.1:7897';
const BASE = 'https://arctic-shift.photon-reddit.com/api/posts/search';
const targetsFile = process.argv[2];
const OUT = process.argv[3] || '_ov2_reddit';
if (!targetsFile) { console.error('用法: node ov-reddit.mjs <targets.json> [outdir]'); process.exit(1); }
fs.mkdirSync(OUT, { recursive: true });
const targets = JSON.parse(fs.readFileSync(targetsFile, 'utf8'));
const sleep = ms => new Promise(r => setTimeout(r, ms));

function curl(url) {
  return new Promise((resolve) => {
    execFile('curl.exe', ['-sL', '-x', PROXY, '-H', 'User-Agent: ' + UA, '--max-time', '60', '--compressed', url],
      { maxBuffer: 1024 * 1024 * 64, windowsHide: true, encoding: 'buffer' }, (err, stdout) => {
        let txt = '';
        if (stdout) txt = Buffer.isBuffer(stdout) ? stdout.toString('utf8') : String(stdout);
        resolve({ err, txt });
      });
  });
}

let ok = 0, bad = 0;
for (let i = 0; i < targets.length; i++) {
  const t = targets[i];
  const qs = new URLSearchParams();
  qs.set('subreddit', t.sub);
  if (t.q) qs.set('query', t.q);
  qs.set('limit', '25');
  qs.set('sort', 'desc');
  if (t.after) qs.set('after', t.after);
  const url = BASE + '?' + qs.toString();
  const outFile = path.join(OUT, (t.sub + '__' + (t.q || 'all')).replace(/[^a-zA-Z0-9]+/g, '_') + '.json');
  if (fs.existsSync(outFile) && fs.statSync(outFile).size > 200) { console.log('SKIP ' + outFile); continue; }
  const { txt } = await curl(url);
  let parsed = null;
  try { parsed = JSON.parse(txt); } catch (e) { }
  if (parsed && Array.isArray(parsed.data)) {
    fs.writeFileSync(outFile, JSON.stringify(parsed.data, null, 1), 'utf8');
    console.log('[' + (i + 1) + '/' + targets.length + '] OK ' + parsed.data.length + '  r/' + t.sub + ' q=' + (t.q || '-') + ' -> ' + outFile);
    ok++;
  } else {
    fs.writeFileSync(outFile + '.err.txt', txt.slice(0, 500), 'utf8');
    console.log('[' + (i + 1) + '/' + targets.length + '] FAIL r/' + t.sub + ' q=' + (t.q || '-') + ' :: ' + txt.slice(0, 160));
    bad++;
    if (bad >= 3) { console.log('连续失败3次，停止'); break; }
  }
  await sleep(13000 + Math.floor(Math.random() * 4000));
}
console.log('DONE ok=' + ok + ' fail=' + bad);
`;
await tools.write({ file_path: "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts\\ov-reddit.mjs", content: code });

